def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    strong_prev = 0.0
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                b = float(prev.get('bid', 0.0))
                prev_bids.append(b)
                if b > strong_prev:
                    strong_prev = b

    if not alive:
        return float(min(budget, 20.0))

    units = int(supply // WATER_REQ)
    scarcity = units <= 1

    urgent = hp <= 4 or no_water >= 2
    very_urgent = hp <= 2 or no_water >= 3

    opp_pressure = strong_prev
    if opp_pressure <= 0:
        opp_pressure = 65.0

    if very_urgent:
        bid = max(92.0, opp_pressure + 1.0)
    elif urgent:
        bid = max(82.0, opp_pressure + 0.75)
    else:
        if scarcity:
            if opp_pressure >= 90.0:
                bid = 18.0 if hp >= 7 and no_water == 0 else 86.0
            elif opp_pressure >= 75.0:
                bid = 28.0 if hp >= 8 and no_water == 0 else opp_pressure + 0.6
            else:
                bid = max(40.0, opp_pressure + 0.6)
        else:
            if opp_pressure >= 85.0:
                bid = 22.0 if hp >= 7 else 72.0
            else:
                bid = max(32.0, opp_pressure * 0.72)

    remaining_days = max(0, 10 - int(day) + 1)
    reserve = 0.0
    if remaining_days > 1 and hp > 3:
        reserve = min(140.0, (remaining_days - 1) * 8.0)
    affordable = max(0.0, budget - reserve)
    if urgent:
        affordable = budget

    bid = min(bid, affordable if affordable > 0 else budget)
    bid = min(bid, budget)
    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

