def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140

    supply = float(day_context['supply'])
    day = day_context['day']

    my_hp = int(my_status['hp'])
    my_budget = float(my_status['budget'])
    my_no_water_days = int(my_status['no_water_days'])

    alive_opps = []
    for k, o in opponents_status.items():
        try:
            if o.get('alive', False):
                alive_opps.append(o)
        except Exception:
            pass

    if not alive_opps:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.4))

    # Use only yesterday's previous_trace bid for immediate reaction.
    prev_bids = []
    for o in alive_opps:
        pt = o.get('previous_trace', {})
        if pt and pt.get('bid') is not None:
            try:
                prev_bids.append(float(pt['bid']))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Baseline: aim to buy roughly 1 unit of water (since WATER_REQ=8) with moderate spending.
    # Supply in [15,25] implies at most ~1-3 units of WATER_REQ.
    # We bias higher when supply is lower (more scarcity) and when our hp is low.
    scarcity = (MAX_SUPPLY - supply) / (MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY != MIN_SUPPLY else 0.5
    scarcity = max(0.0, min(1.0, scarcity))

    # Convert our hp/no-water pressure into a multiplier.
    hp_pressure = 0.0
    if my_hp <= 1:
        hp_pressure = 1.0
    elif my_hp <= 3:
        hp_pressure = 0.7
    elif my_hp <= 5:
        hp_pressure = 0.4
    else:
        hp_pressure = 0.2

    no_water_pressure = 0.0
    if my_no_water_days >= 3:
        no_water_pressure = 1.0
    elif my_no_water_days == 2:
        no_water_pressure = 0.6
    elif my_no_water_days == 1:
        no_water_pressure = 0.3
    else:
        no_water_pressure = 0.0

    pressure = 0.5 * hp_pressure + 0.5 * no_water_pressure

    # If others were bidding very high yesterday, we slightly increase but avoid overpaying.
    # Yesterday: Alex max ~68.6, David max ~94.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        aggression = 0.75
    elif highest_prev_bid >= DAILY_SALARY * 0.45:
        aggression = 0.55
    else:
        aggression = 0.35

    # Target bid: moderate band, scaled by scarcity and pressure.
    # Keep within budget and avoid matching the absolute highest bids.
    base = DAILY_SALARY * (0.25 + 0.25 * scarcity)
    bid = base * (0.6 + 0.8 * pressure) * (0.7 + 0.6 * aggression)

    # Cap: don't exceed what would be a near-max push unless we are in critical condition.
    critical = 1.0 if (my_hp <= 2 or my_no_water_days >= 2) else 0.0
    cap = DAILY_SALARY * (0.95 if critical else 0.65)
    bid = min(bid, cap)

    # If we are critical, still try to outbid moderate opponents.
    if critical and highest_prev_bid > 0:
        bid = max(bid, min(my_budget, highest_prev_bid * 0.65 + 5.0))

    # Final clamp to budget.
    bid = max(0.0, min(float(my_budget), float(bid)))
    return bid
